CREATE VIEW std_play_activity_candidates AS WITH ranked AS (SELECT g.GameID, s.play_status, row_number() OVER (PARTITION BY g.GameID ORDER BY CASE  WHEN ((s.play_status = 'In Progress')) THEN (1) WHEN ((s.play_status = 'Completed')) THEN (2) WHEN ((s.play_status = 'Unplayed')) THEN (3) ELSE 4 END) AS status_rank FROM std_inventory_game_ready AS s INNER JOIN Game AS g ON ((g.GameTitle = s.game_title)))SELECT GameID, play_status FROM ranked WHERE ((status_rank = 1) AND (play_status IS NOT NULL));
